mapper.select:
SELECT
    entry.id,
    entry.actor_account_id,
    actor.email AS actor_email,
    entry.action,
    entry.target_account_id,
    entry.request_summary,
    entry.client_ip,
    entry.user_agent,
    entry.created_at
FROM admin_access_log entry
LEFT JOIN account actor ON actor.id = entry.actor_account_id


        AND entry.actor_account_id = #{actorAccountId}


        AND entry.target_account_id = #{targetAccountId}


        AND entry.action = #{action}


        AND entry.created_at >= #{createdFrom}


        AND entry.created_at < #{createdBefore}


        AND entry.id < #{beforeId}


ORDER BY entry.id DESC
LIMIT #{limit}
